struct Tape {
    enum Op { CONST, INPUT, ADD, MUL, SIN, EXP };

    struct Node {
        double val;
        double grad;
        int    op;
        int    a;
        int    b;
        bool   needs_grad;
    };

    std::vector<Node> nodes;

    int constant(double v) {
        nodes.push_back(Node{v, 0.0, CONST, -1, -1, false});
        return static_cast<int>(nodes.size()) - 1;
    }

    int input(double v) {
        nodes.push_back(Node{v, 0.0, INPUT, -1, -1, true});
        return static_cast<int>(nodes.size()) - 1;
    }

    int add(int a, int b) {
        nodes.push_back(Node{nodes[a].val + nodes[b].val, 0.0, ADD, a, b, true});
        return static_cast<int>(nodes.size()) - 1;
    }

    int mul(int a, int b) {
        nodes.push_back(Node{nodes[a].val * nodes[b].val, 0.0, MUL, a, b, true});
        return static_cast<int>(nodes.size()) - 1;
    }

    int sin_(int a) {
        nodes.push_back(Node{std::sin(nodes[a].val), 0.0, SIN, a, -1, true});
        return static_cast<int>(nodes.size()) - 1;
    }

    int exp_(int a) {
        nodes.push_back(Node{std::exp(nodes[a].val), 0.0, EXP, a, -1, true});
        return static_cast<int>(nodes.size()) - 1;
    }

    double value(int node) const {
        return nodes[node].val;
    }

    void backward(int root) {
        for (auto& n : nodes) n.grad = 0.0;
        nodes[root].grad = 1.0;

        // Reverse recording order: every consumer appears after its inputs,
        // so iterating backward guarantees consumers are processed first.
        for (int i = static_cast<int>(nodes.size()) - 1; i >= 0; --i) {
            const Node& n = nodes[i];
            if (!n.needs_grad || n.grad == 0.0) continue;
            const double g = n.grad;
            switch (n.op) {
                case ADD:
                    if (nodes[n.a].needs_grad) nodes[n.a].grad += g;
                    if (nodes[n.b].needs_grad) nodes[n.b].grad += g;
                    break;
                case MUL:
                    if (nodes[n.a].needs_grad) nodes[n.a].grad += g * nodes[n.b].val;
                    if (nodes[n.b].needs_grad) nodes[n.b].grad += g * nodes[n.a].val;
                    break;
                case SIN:
                    if (nodes[n.a].needs_grad) nodes[n.a].grad += g * std::cos(nodes[n.a].val);
