                case EXP:
                    if (nodes[n.a].needs_grad) nodes[n.a].grad += g * n.val; // d/dx e^x = e^x
                    break;
                default:
                    break;
            }
        }
    }

    double grad(int node) const {
        return nodes[node].grad;
    }
